// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/DEXI.sol";

contract DEXIMintTest is Test {
    DEXI token;
    uint256 constant MAX_SUPPLY_MULTIPLIER = 5;
    uint256 public INITIAL_SUPPLY;
    uint256 public MAX_SUPPLY;
    address constant OWNER = address(1);

    function setUp() public {
        vm.prank(OWNER);
        token = new DEXI();
        INITIAL_SUPPLY = token.totalSupply();
        MAX_SUPPLY = INITIAL_SUPPLY * MAX_SUPPLY_MULTIPLIER;
    }

    function testMintUntilMaxSupply() public {
        uint256 currentSupply = token.totalSupply();

        // Mint until max supply is reached
        while (currentSupply < MAX_SUPPLY) {
            uint256 annualMint = currentSupply * 10 / 100; // 10% of current supply

            // Adjust last mint to fit exactly at max supply
            if (currentSupply + annualMint > MAX_SUPPLY) {
                annualMint = MAX_SUPPLY - currentSupply;
            }

            vm.prank(OWNER);
            token.mint(OWNER, annualMint);
            currentSupply = token.totalSupply();

            // Advance to next year
            vm.warp(block.timestamp + 366 days);
        }

        assertEq(currentSupply, MAX_SUPPLY, "Max supply not reached");

        // Attempt minting beyond max supply
        vm.prank(OWNER);
        vm.expectRevert("Mint limit reached");
        token.mint(OWNER, 1);
    }

    function testYearlyMintLimit() public {
        // First 10% mint in current year
        uint256 annualMint = token.totalSupply() * 10 / 100;
        vm.prank(OWNER);
        token.mint(OWNER, annualMint);

        // Attempt second mint in same year
        vm.prank(OWNER);
        vm.expectRevert("it exceeds max mintable amount");
        token.mint(OWNER, 1);

        // Advance 366 days to next year
        vm.warp(block.timestamp + 366 days);

        // Should succeed in new year
        annualMint = token.totalSupply() * 10 / 100;
        vm.prank(OWNER);
        token.mint(OWNER, annualMint);
    }
}
