        token = new DEXI();
        INITIAL_SUPPLY = token.totalSupply();
        MAX_SUPPLY = INITIAL_SUPPLY * MAX_SUPPLY_MULTIPLIER;
    }

    // --- Differential helpers ---
    function _isLeapYear(uint256 year) internal pure returns (bool) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    function _getYear(uint256 timestamp) internal pure returns (uint256) {
        uint256 daysSinceEpoch = timestamp / 1 days;
        uint256 year = 1970;
        while (true) {
            uint256 daysInYear = _isLeapYear(year) ? 366 : 365;
            if (daysSinceEpoch < daysInYear) {
                return year;
            }
            daysSinceEpoch -= daysInYear;
            year++;
        }
        return year; // unreachable, added to satisfy compiler
    }

    function _snapshot() internal view returns (uint256 supply, uint256 ownerBal, uint256 yearMinted) {
        supply = token.totalSupply();
        ownerBal = token.balanceOf(OWNER);
        yearMinted = token._yearMintedAmount(_getYear(block.timestamp));
    }

    function _logSnapshot(string memory label, uint256 supply, uint256 ownerBal, uint256 yearMinted) internal {
        console2.log(label);
        console2.log("  totalSupply:", supply);
        console2.log("  OWNER balance:", ownerBal);
        console2.log("  yearMintedAmount:", yearMinted);
    }

    function _logComparison(
        string memory label,
        uint256 supplyBefore,
        uint256 ownerBefore,
        uint256 yearBefore,
        uint256 supplyAfter,
        uint256 ownerAfter,
        uint256 yearAfter
    ) internal {
        bool supplyChanged = supplyAfter != supplyBefore;
        bool ownerChanged = ownerAfter != ownerBefore;
        bool yearChanged = yearAfter != yearBefore;
        console2.log(label);
        console2.log("  totalSupply changed:", supplyChanged ? "YES" : "NO");
        console2.log("  OWNER balance changed:", ownerChanged ? "YES" : "NO");
        console2.log("  yearMintedAmount changed:", yearChanged ? "YES" : "NO");
        console2.log("  state changed:", (supplyChanged || ownerChanged || yearChanged) ? "YES" : "NO");
    }

    function testMintUntilMaxSupply() public {
        uint256 currentSupply = token.totalSupply();

        // --- BEFORE-Trigger Initial State ---
        (uint256 initSupply, uint256 initOwnerBal, uint256 initYearMinted) = _snapshot();
        _logSnapshot("--- BEFORE-Trigger Initial State ---", initSupply, initOwnerBal, initYearMinted);

        // Mint until max supply is reached
        while (currentSupply < MAX_SUPPLY) {
            uint256 annualMint = currentSupply * 10 / 100; // 10% of current supply

            // Adjust last mint to fit exactly at max supply
            if (currentSupply + annualMint > MAX_SUPPLY) {
                annualMint = MAX_SUPPLY - currentSupply;
            }

            // --- BEFORE-Trigger Mint ---
            (uint256 supplyBefore, uint256 ownerBefore, uint256 yearBefore) = _snapshot();
            _logSnapshot("--- BEFORE-Trigger Mint ---", supplyBefore, ownerBefore, yearBefore);
            console2.log("  annualMint:", annualMint);

            vm.prank(OWNER);
            token.mint(OWNER, annualMint);

            // --- AFTER-Trigger Mint ---
            (uint256 supplyAfter, uint256 ownerAfter, uint256 yearAfter) = _snapshot();
            _logSnapshot("--- AFTER-Trigger Mint ---", supplyAfter, ownerAfter, yearAfter);
            _logComparison("  Mint state comparison:", supplyBefore, ownerBefore, yearBefore, supplyAfter, ownerAfter, yearAfter);

            currentSupply = token.totalSupply();

            // Advance to next year
            vm.warp(block.timestamp + 366 days);
        }

        assertEq(currentSupply, MAX_SUPPLY, "Max supply not reached");

        // --- BEFORE-Trigger MintBeyondMax ---
        (uint256 supplyBeforeRevert, uint256 ownerBeforeRevert, uint256 yearBeforeRevert) = _snapshot();
        _logSnapshot("--- BEFORE-Trigger MintBeyondMax ---", supplyBeforeRevert, ownerBeforeRevert, yearBeforeRevert);

        // Use low-level call to capture whether the limit-exceeding mint succeeds
        vm.prank(OWNER);
        (bool success, ) = address(token).call(abi.encodeWithSignature("mint(address,uint256)", OWNER, uint256(1)));

        // --- AFTER-Trigger MintBeyondMax ---
        (uint256 supplyAfterRevert, uint256 ownerAfterRevert, uint256 yearAfterRevert) = _snapshot();
        _logSnapshot("--- AFTER-Trigger MintBeyondMax ---", supplyAfterRevert, ownerAfterRevert, yearAfterRevert);
        console2.log("  MintBeyondMax succeeded:", success ? "YES" : "NO");
        _logComparison("  MintBeyondMax state comparison:", supplyBeforeRevert, ownerBeforeRevert, yearBeforeRevert, supplyAfterRevert, ownerAfterRevert, yearAfterRevert);

        // Preserve original expectation that minting beyond max supply must revert.
        assertFalse(success, "Mint limit reached");
    }

    function testYearlyMintLimit() public {
        // --- BEFORE-Trigger Yearly Limit Test ---
        (uint256 initSupply, uint256 initOwnerBal, uint256 initYearMinted) = _snapshot();
        _logSnapshot("--- BEFORE-Trigger Yearly Limit Test ---", initSupply, initOwnerBal, initYearMinted);

        // First 10% mint in current year
