        vm.prank(OWNER);
        token.mint(OWNER, annualMint);

        (uint256 supplyAfter1, uint256 ownerAfter1, uint256 yearAfter1) = _snapshot();
        _logSnapshot("--- AFTER-Trigger First Mint ---", supplyAfter1, ownerAfter1, yearAfter1);
        _logComparison("  First Mint state comparison:", supplyBefore1, ownerBefore1, yearBefore1, supplyAfter1, ownerAfter1, yearAfter1);

        // Attempt second mint in same year
        (uint256 supplyBefore2, uint256 ownerBefore2, uint256 yearBefore2) = _snapshot();
        _logSnapshot("--- BEFORE-Trigger Second Mint (same year) ---", supplyBefore2, ownerBefore2, yearBefore2);

