        _logComparison("  Second Mint state comparison:", supplyBefore2, ownerBefore2, yearBefore2, supplyAfter2, ownerAfter2, yearAfter2);

        // Preserve original expectation that a second mint in the same year must revert.
        assertFalse(secondMintSuccess, "it exceeds max mintable amount");

        // Advance 366 days to next year
        vm.warp(block.timestamp + 366 days);

        // Should succeed in new year
        (uint256 supplyBefore3, uint256 ownerBefore3, uint256 yearBefore3) = _snapshot();
        _logSnapshot("--- BEFORE-Trigger Third Mint (new year) ---", supplyBefore3, ownerBefore3, yearBefore3);
        annualMint = token.totalSupply() * 10 / 100;
        console2.log("  annualMint:", annualMint);

        vm.prank(OWNER);
        token.mint(OWNER, annualMint);

        (uint256 supplyAfter3, uint256 ownerAfter3, uint256 yearAfter3) = _snapshot();
        _logSnapshot("--- AFTER-Trigger Third Mint (new year) ---", supplyAfter3, ownerAfter3, yearAfter3);
        _logComparison("  Third Mint state comparison:", supplyBefore3, ownerBefore3, yearBefore3, supplyAfter3, ownerAfter3, yearAfter3);
    }

    // Final differential verdict: placed at the end of the script so exactly one final line is printed.
    function testZZZDifferentialFinalVerdict() public {
        // Establish the same state as the PoC's yearly limit test
        uint256 annualMint = token.totalSupply() * 10 / 100;
        vm.prank(OWNER);
        token.mint(OWNER, annualMint);

        // --- BEFORE-Trigger Final Differential ---
        (uint256 supplyBefore, uint256 ownerBefore, uint256 yearBefore) = _snapshot();
        _logSnapshot("--- BEFORE-Trigger Final Differential (second mint same year) ---", supplyBefore, ownerBefore, yearBefore);

        // TRIGGER: attempt a second mint in the same year
        vm.prank(OWNER);
        (bool success, ) = address(token).call(abi.encodeWithSignature("mint(address,uint256)", OWNER, uint256(1)));

        // --- AFTER-Trigger Final Differential ---
        (uint256 supplyAfter, uint256 ownerAfter, uint256 yearAfter) = _snapshot();
        _logSnapshot("--- AFTER-Trigger Final Differential (second mint same year) ---", supplyAfter, ownerAfter, yearAfter);

        bool stateChanged = (supplyAfter != supplyBefore) || (ownerAfter != ownerBefore) || (yearAfter != yearBefore);
        console2.log("  Second mint succeeded:", success ? "YES" : "NO");
        console2.log("  State changed:", stateChanged ? "YES" : "NO");

        if (success && stateChanged) {
            console2.log("Vulnerability Exists: A second mint in the same year succeeded and modified totalSupply/OWNER balance/yearMintedAmount");
        } else {
            console2.log("Vulnerability not Exist: A second mint in the same year reverted and did not modify totalSupply/OWNER balance/yearMintedAmount");
        }
    }
}
